begin;
create extension if not exists pgcrypto;
create table if not exists organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table if not exists auth_users(id uuid primary key default gen_random_uuid(),organization_id uuid references organizations(id),email text not null unique,password_hash text not null,name text not null,role text not null default 'admin',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists auth_login_attempts(id bigserial primary key,email text not null,ip_hash text not null,succeeded boolean not null,attempted_at timestamptz not null default now());
create index if not exists auth_login_attempts_window on auth_login_attempts(email,ip_hash,attempted_at desc);
create table if not exists commercial_accounts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),cnpj char(14) not null,product text not null,owner text,stage text not null default 'new',last_contact_at timestamptz,next_activity_at timestamptz,notes text,lead_origin text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,cnpj,product));
create table if not exists commercial_interactions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),account_id uuid not null references commercial_accounts(id) on delete cascade,interaction_type text not null,summary text not null,owner text,occurred_at timestamptz not null default now(),created_at timestamptz not null default now());
create table if not exists prospect_lists(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,product text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists prospect_list_items(list_id uuid references prospect_lists(id) on delete cascade,cnpj char(14) not null,added_at timestamptz not null default now(),primary key(list_id,cnpj));
create table if not exists enrichment_evidence(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),cnpj char(14) not null,field_type text not null,value text not null,source_url text not null,verified_at timestamptz not null,confidence text not null,conflicts_with_registry boolean not null default false,manual_override boolean not null default false,created_at timestamptz not null default now());
create table if not exists company_summaries(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),cnpj char(14) not null,summary text not null,verified_at timestamptz not null,created_at timestamptz not null default now(),unique(organization_id,cnpj));
create table if not exists company_summary_sources(summary_id uuid references company_summaries(id) on delete cascade,source_url text not null,title text,accessed_at timestamptz not null,primary key(summary_id,source_url));
create table if not exists schema_migrations(version text primary key,applied_at timestamptz not null default now());
insert into schema_migrations(version) values('001_online_foundation') on conflict do nothing;
commit;
